     32	// serveAttachmentFile serves attachment binary content using native HTTP.
     33	func (s *FileServerService) serveAttachmentFile(c *echo.Context) error {
     34		ctx := c.Request().Context()
     35		uid := c.Param("uid")
     36		wantThumbnail := c.QueryParam("thumbnail") == "true"
     37		wantMotion := c.QueryParam("motion") == "true"
     38	
     39		attachment, err := s.Store.GetAttachment(ctx, &store.FindAttachment{
     40			UID:     &uid,
     41			GetBlob: true,
     42		})
     43		if err != nil {
     44			return echo.NewHTTPError(http.StatusInternalServerError, "failed to get attachment").Wrap(err)
     45		}
     46		if attachment == nil {
     47			return echo.NewHTTPError(http.StatusNotFound, "attachment not found")
     48		}
     49	
     50		if err := s.checkAttachmentPermission(ctx, c, attachment); err != nil {
     51			return err
     52		}
     53	
     54		if wantMotion {
     55			return s.serveMotionClip(c, attachment)
     56		}
     57	
     58		contentType := s.sanitizeContentType(attachment.Type)
     59	
     60		// Stream video/audio to avoid loading entire file into memory.
     61		if isMediaType(attachment.Type) {
     62			return s.serveMediaStream(c, attachment, contentType)
     63		}
     64	
     65		return s.serveStaticFile(c, attachment, contentType, wantThumbnail)
     66	}
